import statistics
from common import *


def main():
    occupancy=json.loads((HERE/'occupancy.json').read_text())
    screen=json.loads((HERE/'screen.json').read_text())
    timings=json.loads((HERE/'timings.json').read_text())
    profiles=json.loads((HERE/'profiles.json').read_text())
    memory=json.loads((HERE/'memory.json').read_text())
    validation=json.loads((HERE/'validation.json').read_text())
    def med(name,label):return next(r['median'] for r in timings['summary'] if r['image']==name and r['variant']==label)
    def stage(name,label,key):return statistics.median(r['spans'][key] for r in profiles['rows'] if r['image']==name and r['variant']==label)
    def peak(name,label):return statistics.median(r['peak_rss'] for r in memory['rows'] if r['image']==name and r['variant']==label)/1048576
    def save(name,lines):(HERE/name).write_text('\n'.join(lines)+'\n',encoding='utf-8',newline='\n')
    lines=['# Pass 22 block feasibility','','Saved P21S q128 Googlewiki/Cat and q32 Eiffel; no encodes or reference regeneration. Start a0824ff1a319f6cadcfbc16d146f666ec9f91832. Full input/source identities are in provenance.json and occupancy.json. Components are the fixed orthonormal transform components, not RGB channels. Each component block contains 64 coefficients.','','| Image | Spatial blocks | Component blocks | Empty component blocks | Empty spatial blocks | Pixels covered by any occupied component |','| --- | ---: | ---: | ---: | ---: | ---: |']
    for r in occupancy['rows']:
        lines.append(f"| {r['image']} | {r['spatial_blocks']:,} | {r['component_blocks']:,} | {100*r['component_zero_fraction']:.2f}% | {r['spatial_zero_blocks']:,} ({100*r['spatial_zero_fraction']:.2f}%) | {100*r['source_pixel_coverage']:.2f}% |")
    lines+=['','Coverage clips edge blocks to the true source dimensions. Component emptiness estimates the share of64-point transforms that can be skipped; it does not predict whole-decoder savings. Spatial coverage remains high on Eiffel, and output storage/base decoding still covers every source pixel.','','| Image | Empty | One nonzero | 2-4 nonzeros | More than 4 | Occupied components 0 / 1 / 2 |','| --- | ---: | ---: | ---: | ---: | ---: |']
    for r in occupancy['rows']:
        counts=r['component_count_histogram']
        lines.append(f"| {r['image']} | {counts['zero']:,} | {counts['one']:,} | {counts['two_to_four']:,} | {counts['over_four']:,} | {' / '.join(str(x) for x in r['component_nonzero_counts'])} |")
    lines+=['','The frozen gate required at least 20% empty spatial blocks on two of three cases. Googlewiki and Cat pass; Eiffel is the low-sparsity control. One implementation gathers nonzero component blocks, runs the same SciPy float32 orthonormal IDCT on the compact batch, and scatters into a zero-filled dense spatial buffer. The representation, quantizer and coefficients are unchanged. There is no per-image routing rule.','','Spatial distribution: occupied fractions in a 4x4 grid of block-coordinate regions (equal block-count splits; exact fractions plus per-component maps are in occupancy.json).']
    for r in occupancy['rows']:
        lines+=['',r['image'],'','| Region row | Col1 | Col2 | Col3 | Col4 |','| --- | ---: | ---: | ---: | ---: |']
        for i,values in enumerate(r['spatial_occupied_fraction_4x4']):lines.append(f"| {i+1} | "+' | '.join(f'{100*v:.1f}%' for v in values)+' |')
    lines+=['','Cat has near-empty top regions but substantial occupancy below. Googlewiki emptiness is spread across the image. Eiffel is occupied nearly everywhere. Coefficient sparsity alone would not have established any of these facts.','','Three warmed rotated full-call diagnostic repetitions, before the separate final HQ comparison:','','| Image | Frozen ms | Sparse only ms | Reuse only ms | Combined ms |','| --- | ---: | ---: | ---: | ---: |']
    for name in CASES:
        vals=[statistics.median(r['seconds'] for r in screen['rows'] if r['image']==name and r['variant']==v)*1000 for v in ('reference','sparse_only','reuse_only','sparse_reuse')]
        lines.append('| '+name+' | '+' | '.join(f'{x:.2f}' for x in vals)+' |')
    lines+=['','The sparse path materially improves Googlewiki/Cat full calls, with little standalone benefit on Eiffel. Compact contiguous transforms also change memory locality; do not attribute all IDCT savings solely to the empty-block percentage. Gathering/scattering overhead and dense output remain. No second selection method or custom transform was attempted. Final comparative numbers use the separately interleaved benchmark in the reconstruction report.']
    save('PBC_SPARSE_BLOCK_FEASIBILITY.md',lines)
    lines=['# Pass 22 reconstruction results','','One sparse gather/IDCT/scatter method and one buffer-reuse method. No fused Numba kernel was implemented: compatible in-place NumPy/SciPy operations were sufficient to test the allocation hypothesis without changing color arithmetic. Frozen Pass21 remains the regression decoder; research_pass22.decoder.decode reads the identical P21S container through the unchanged split/read_coefficients functions.','','The selected float32 block buffer is scaled in place and passed to SciPy with overwrite_x=True. Measured buffer sharing confirms that IDCT reuses it. The base remains uint8. The color-correction buffer receives base addition, np.rint and np.clip in place, then is converted to final uint8. The same float32 color matrix/matmul and rounding are preserved. Dense reuse-only and sparse-only flags exist for diagnostic ablations, not automatic routing.','','Actual allocations and views:','','- Sparse recovery still allocates the complete frequency-ordered int16 coefficient buffer (2 bytes per coefficient). q reshape/transpose shares that memory.','- Expression-level tracing confirms original astype(float32)*step temporarily materializes two 4-byte-per-coefficient arrays. Non-overwriting IDCT produces another.','- Sparse selection q!=0 temporarily allocates one byte per coefficient, then a three-component block mask. Boolean gathering allocates occupied int16 blocks; conversion allocates occupied float32 blocks.','- Sparse reconstruction still allocates a dense 4-byte-per-coefficient spatial buffer. Its transpose is a view, but the subsequent image reshape materializes another full padded float array; np.shares_memory is false. The crop is a view.','- Fixed color matmul allocates a source-size float32 RGB correction. Original base-to-float and add/rint/clip results require more source-size float arrays. The optimized base is uint8 and add/rint/clip reuse the correction; final uint8 output remains.','- Allocation estimates below are logical buffer sizes, not sums of simultaneous live bytes. The profile retains buffers for inspection and must not be used as a peak-memory measurement.','','| Image | Dense int16 MB | One padded float buffer MB | Base float -> uint8 MB | Occupied float buffer MB | Occupancy comparison temporary MB |','| --- | ---: | ---: | ---: | ---: | ---: |']
    for name in CASES:
        r=next(r for r in profiles['rows'] if r['image']==name and r['variant']=='optimized');b=r['buffers']
        pixels=b['base']['bytes'];n=b['dense_int16']['bytes']/2
        lines.append(f"| {name} | {b['dense_int16']['bytes']/1e6:.3f} | {b['spatial']['bytes']/1e6:.3f} | {pixels*4/1e6:.3f} -> {pixels/1e6:.3f} | {b['selected_float']['bytes']/1e6:.3f} | {n/1e6:.3f} |")
    lines+=['','MB above is decimal; memory peaks below use MiB. For Cat, each dense float image is 102.30 MB; the occupied transform batch is 25.28 MB. This avoids dense transform input/output work but retains dense scatter, layout conversion and RGB reconstruction.','','Final whole-decoder timing: saved streams; i9-12900H logical P-core 12; Python 3.11.16, NumPy 2.4.6, Numba 0.68.0, SciPy 1.17.1, Pillow 11.3.0; one numerical thread/FFT worker. One full warmup per actual stream/variant then three rotated interleaved repetitions. Includes parsing, base decode, sparse recovery, transforms and uint8 output. I/O, hashing, logging and external scoring excluded. Ordinary HQ is its saved authentic practical-codec operating point, not matched-rate output.','','| Image | HQ ms | Frozen P21S ms | Optimized ms | Full-call reduction | Speedup | Optimized / HQ |','| --- | ---: | ---: | ---: | ---: | ---: | ---: |']
    for name in CASES:
        ordinary,old,new=(med(name,v) for v in ('ordinary_hq','reference','optimized'))
        lines.append(f'| {name} | {ordinary*1000:.2f} | {old*1000:.2f} | {new*1000:.2f} | {100*(1-new/old):.2f}% | {old/new:.2f}x | {new/ordinary:.2f}x |')
    lines+=['','| Image | Variant | Mean ms | Median ms | Min-max ms | CV |','| --- | --- | ---: | ---: | ---: | ---: |']
    for r in timings['summary']:lines.append(f"| {r['image']} | {r['variant']} | {r['mean']*1000:.2f} | {r['median']*1000:.2f} | {r['minimum']*1000:.2f}-{r['maximum']*1000:.2f} | {r['cv_percent']:.2f}% |")
    lines+=['','All three complete rounds favor optimized over frozen on each image. Eiffel improvement is small. Final timings differ from Pass21 and the preliminary screen; use contemporary interleaved ratios, not historical absolute numbers. Three repetitions give local feasibility evidence, not HF performance or broad statistical certainty.','','Stage medians in ms, measured separately with three warmed alternating disjoint profiles. Instrumentation, cache state and retained arrays change runtime; these numbers do not replace full-call medians and their median sums are not observed complete calls.','','| Image | Variant | Base | Recovery | Selection + gather | Dequant | IDCT | Zero + scatter | Reorder copy | Color | Final output |','| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |']
    for name in CASES:
        for label in ('reference','optimized'):
            keys=('base_decode','recovery','selection','dequantize','idct','scatter','reorder_copy','color','final_output')
            values=[]
            for key in keys:
                if key=='recovery':value=stage(name,label,'decompress')+stage(name,label,'unpack')
                elif key=='selection':value=stage(name,label,'block_selection')+stage(name,label,'gather') if label=='optimized' else 0
                elif key=='scatter':value=stage(name,label,'zero_output')+stage(name,label,'scatter') if label=='optimized' else 0
                else:value=stage(name,label,key)
                values.append(value*1000)
            lines.append('| '+name+' | '+label+' | '+' | '.join(f'{v:.2f}' for v in values)+' |')
    lines+=['','Sparse selection/scatter cost is counted, not hidden. For Cat the profiled IDCT falls from about 320 to 59 ms, while selection/gather/scatter consumes about 44 ms. Dense layout/color/final work remains around 224 ms. Lower base-stage time includes avoiding float conversion and measurement variation; it is not evidence of a changed PBC base algorithm.','','Isolated memory: two fresh processes per image/variant; both paths warmed on the same tiny decoder-only fixture, then one actual target decode. Record pre-call RSS and native Windows peak_wset; read peak before output hashing/scoring. No baseline decoded target or profile arrays coexist. Imported-runtime/warmup memory is included, with no claim that cumulative high-water marks isolate individual allocations. Here pre-call peaks equal pre-call RSS, so target peaks exceed them.','','| Image | Frozen process peak MiB | Optimized peak MiB | Change | Frozen / optimized increase over pre-call RSS MiB |','| --- | ---: | ---: | ---: | ---: |']
    for name in CASES:
        old,new=peak(name,'reference'),peak(name,'optimized')
        increments=[statistics.median(r['peak_above_baseline_rss'] for r in memory['rows'] if r['image']==name and r['variant']==label)/1048576 for label in ('reference','optimized')]
        lines.append(f'| {name} | {old:.2f} | {new:.2f} | {100*(new/old-1):+.2f}% | {increments[0]:.2f} / {increments[1]:.2f} |')
    lines+=['','The small Eiffel peak regression is real in these fresh processes (roughly 1.5 MiB, 1.2% total); denser occupancy requires a relatively large gathered batch plus dense scatter. Cat saves roughly 49 MiB but still peaks near 503 MiB. Raw per-process RSS/peak measurements and both repeats remain in memory.json. No general memory-improvement claim is made across untested images.','','Correctness: all six saved streams retain their byte hashes and exact frozen uint8 RGB dimensions/pixels/SHA256/original-resolution MSE, with repeat determinism on sparse-only, reuse-only and combined paths. 32 decoder-only synthetic containers cover 1x1, 8x8, 13x9, 35x37, steps 32/128, all-zero, single occupied component, mixed sparse/dense and signed int16 extremes at image edges. Every candidate matches the frozen decoder. 31 malformed/resource cases reject in reference and all three candidate paths, including counts, malformed/canonical varints, overflow, truncation, XZ trailing/concatenated/over-expanding content, dimensions/pixel/file caps and mismatched base dimensions. Two fresh processes decode saved Googlewiki/Flower with model loading and image encoding forbidden. No input validation was bypassed and no new compiled indexing kernel was introduced.','','Existing bounded P21S/coefficient handling is reused unchanged. All experiments in this pass use only saved image streams or manually framed zero-patch fixture bases, never full-image encoding.']
    allocation=json.loads((HERE/'allocations.json').read_text())
    lines+=['','Expression-level allocation check (tracemalloc after inputs already exist; tracks NumPy-registered buffers, not every native allocation):','','| Image | Original dequant traced peak MB | Original final expression peak MB | Reused final expression peak MB |','| --- | ---: | ---: | ---: |']
    for name in CASES:
        values=[next(r['traced_peak']/1e6 for r in allocation['rows'] if r['image']==name and r['operation']==op) for op in ('original_dequant_expression','original_final_expression','reuse_final_expression')]
        lines.append('| '+name+' | '+' | '.join(f'{v:.3f}' for v in values)+' |')
    lines+=['','The intact dequantization expression peaks at about twice its output buffer. Cat final add/rint/clip/cast peaks at 204.61 MB of new traced allocations in the original expression versus 25.58 MB with reuse (the final uint8 output). Inputs and pre-existing correction are excluded. These expression peaks do not add to process peaks and are not timing evidence.']
    save('PBC_DECODER_RECONSTRUCTION_RESULTS.md',lines)
    lines=['# Pass 22 summary','','Outcome B: material exact-pixel decoder improvement, with a large remaining photographic cost. Preserve research_pass22.decoder.decode as the optimized experimental P21S reader and retain frozen Pass21 unchanged. No production promotion.','','1. Empty component / spatial blocks: Googlewiki 69.84% /49.09%; Eiffel 33.77% /5.05%; Cat 75.29% /37.82%. Source pixels covered by any occupied component: 50.78%,94.93%,62.18%.','2. Block skipping is justified on Googlewiki/Cat, not by spatial sparsity on Eiffel. One compact component-batch SciPy IDCT plus dense scatter was implemented; no custom transform or selection redesign.','3. Buffer reuse succeeded: in-place dequantization/IDCT, uint8 base and in-place correction add/rint/clip. No fused scalar kernel. Dense int16, dense scatter, materialized block-to-image reshape, color correction and final output still exist.','4. Exact uint8 pixels, dimensions, SHA256 and original-resolution MSE pass all six frozen files and all 32 synthetic boundary/zero/sparse/dense/extreme fixtures. Repeat decoding is deterministic. 31 invalid/resource cases and two model/encoder-forbidden file-only processes pass. Representation and encoded bytes are unchanged.','','| Image | Ordinary HQ ms | Frozen P21S ms | Optimized ms | Reduction vs frozen | Overhead vs HQ |','| --- | ---: | ---: | ---: | ---: | ---: |']
    for name in CASES:
        ordinary,old,new=(med(name,v) for v in ('ordinary_hq','reference','optimized'))
        lines.append(f'| {name} | {ordinary*1000:.2f} | {old*1000:.2f} | {new*1000:.2f} | {100*(1-new/old):.2f}% | {100*(new/ordinary-1):+.2f}% |')
    lines+=['','These are three warmed rotated full-call repetitions, saved streams, same pinned CPU and one numerical thread. Per-repeat values, means/medians/ranges/CV and all source/input hashes accompany the reports. Optimized CV is 7.06% Googlewiki, 2.59% Eiffel, 4.33% Cat. Small Eiffel changes merit limited confidence; Googlewiki/Cat reductions are larger. No HF speed claim.','','5. Isolated process peaks: Googlewiki 146.58 ->143.08MiB; Eiffel 123.73 ->125.19MiB; Cat 551.73 ->502.86MiB (medians of two fresh processes each). Memory improves on Googlewiki/Cat and slightly regresses on Eiffel. Cat still requires hundreds of MiB.','','Amdahl check using contemporary complete-call medians:','','| Image | 1.15 x HQ target ms | Optimized ms | Further saving needed ms | Fraction of optimized time |','| --- | ---: | ---: | ---: | ---: |']
    for name in CASES:
        target=1.15*med(name,'ordinary_hq');new=med(name,'optimized');gap=max(0,new-target)
        lines.append(f'| {name} | {target*1000:.2f} | {new*1000:.2f} | {gap*1000:.2f} | {100*gap/new:.1f}% |')
    lines+=['','Eiffel already approaches the aspirational target locally. Googlewiki needs about 9.5 ms more removed; its remaining layout/color/final profile contains enough work for that to be plausible, without a guarantee of pixel-exact implementation or transfer to other images. Cat needs about 374 ms more, roughly71% of its already optimized full call. Its remaining IDCT is only about 59 ms in the separate profile. Even removing that operation cannot close the gap; dense output passes, base decoding and coefficient recovery remain. Profile observations are not immutable lower bounds, but do not support a credible small-change route to ordinary Cat latency.','','Recommendation: retain the useful optimized prototype and Pass21 storage work. Do not start another general-purpose hybrid optimization campaign or tune entropy further. A later bounded block-oriented/fused-output study could have credible upside for small/medium images if optional-mode generalization becomes the objective; it is not justified as a promise to solve the large-image target. No such kernel or activation study was launched here. Current evidence favors an optional experimental mode, not a general-purpose replacement: Cat/Flower RD failures remain and Cat decode remains 3.90x HQ. General-purpose progress should reconsider the architecture rather than accumulate tiny decoder tweaks.','','Reproduction uses Python 3.11 with ../research_pass17/requirements.txt, the saved six P21S files matching research_pass21/files.json, saved ordinary HQ files matching research_pass17/baseline.json, and restored original hpt_data for independent MSE. No cached dense coefficient arrays or new encoder runs are required. Restore ignored saved streams from the local research archive; their exact hashes are in provenance.json. Run from repository root:','','```','research_pass16/.venv/Scripts/python.exe research_pass22/occupancy.py','research_pass16/.venv/Scripts/python.exe research_pass22/screen.py','research_pass16/.venv/Scripts/python.exe research_pass22/benchmark.py','research_pass16/.venv/Scripts/python.exe research_pass22/profile.py','research_pass16/.venv/Scripts/python.exe research_pass22/memory.py','research_pass16/.venv/Scripts/python.exe research_pass22/allocations.py','research_pass16/.venv/Scripts/python.exe research_pass22/validate.py','research_pass16/.venv/Scripts/python.exe research_pass22/report.py','```','','Direct decoder API: from research_pass22.decoder import decode; decode(saved_p21s_bytes) returns uint8 RGB. Default path is the measured combined method; diagnostic sparse/reuse booleans do not alter representation. Frozen research_pass21.sparse_hybrid.decode remains available. Sources and compact evidence stay on research/experiments; generated streams/arrays/caches and benchmark logs are excluded. Final verified GitHub commit/HEAD is provided in the chat handoff.','','Practical pbc31_feature_histogram, learned model, v0, frozen Pass17/20/21, HF deployment and release staging are unchanged. Staged ZIP SHA256 remains 08855cb3369000fd50d38fbb41d65920899998d366812c04519302383d873591. No release publication, tag, protected branch change, full 25x4 benchmark or followup experiment.']
    save('PBC_PASS22_SUMMARY.md',lines)
    result=meta();result.pop('timing',None)
    result['measurement_protocol']='Use the per-experiment root timing/note and Pass22 reports; inherited control provenance describes source identity, not measurement count.'
    result['streams']={name:{'hybrid':{k:saved(name)[1][k] for k in ('stream_sha256','pixels_sha256','file','step','rgb_mse','bytes')},'ordinary_hq':{k:saved(name,True)[1][k] for k in ('stream_sha256','pixels_sha256','file','rgb_mse','bytes')}} for name in [r['image'] for r in validation['files']]}
    result['input_evidence_sha256']={name:sha((ROOT/name).read_bytes()) for name in ('research_pass21/files.json','research_pass17/baseline.json')}
    result['evidence_sha256']={p.name:sha(p.read_bytes()) for p in HERE.glob('*.json') if p.name!='provenance.json'}
    result['staged_zip_sha256_unchanged']='08855cb3369000fd50d38fbb41d65920899998d366812c04519302383d873591'
    write('provenance.json',result)
    print('reports written; outcome B, preserve experimental decoder; no general-purpose promotion',flush=True)


if __name__=='__main__':main()
